      <div class={`${clsPrefix}-base-loading`} role="img" aria-label="loading">
        <NIconSwitchTransition>
          {{
            default: () =>
              this.show ? (
                <div
                  key="icon"
                  class={`${clsPrefix}-base-loading__transition-wrapper`}
                >
                  <div class={`${clsPrefix}-base-loading__container`}>
                    <svg
                      class={`${clsPrefix}-base-loading__icon`}
                      viewBox={`0 0 ${2 * scaledRadius} ${2 * scaledRadius}`}
                      xmlns="http://www.w3.org/2000/svg"
                      style={{ color: stroke }}
                    >
                      <g>
                        <animateTransform
                          attributeName="transform"
                          type="rotate"
                          values={`0 ${scaledRadius} ${scaledRadius};270 ${scaledRadius} ${scaledRadius}`}
                          begin="0s"
                          dur={duration}
                          fill="freeze"
                          repeatCount="indefinite"
                        />
                        <circle
                          class={`${clsPrefix}-base-loading__icon`}
                          fill="none"
                          stroke="currentColor"
                          stroke-width={strokeWidth}
                          stroke-linecap="round"
                          cx={scaledRadius}
                          cy={scaledRadius}
                          r={radius - strokeWidth / 2}
                          stroke-dasharray={5.67 * radius}
                          stroke-dashoffset={18.48 * radius}
                        >
                          <animateTransform
                            attributeName="transform"
                            type="rotate"
                            values={`0 ${scaledRadius} ${scaledRadius};135 ${scaledRadius} ${scaledRadius};450 ${scaledRadius} ${scaledRadius}`}
                            begin="0s"
                            dur={duration}
                            fill="freeze"
                            repeatCount="indefinite"
                          />
                          <animate
                            attributeName="stroke-dashoffset"
                            values={`${5.67 * radius};${1.42 * radius};${
                              5.67 * radius
                            }`}
                            begin="0s"
                            dur={duration}
                            fill="freeze"
                            repeatCount="indefinite"
                          />
                        </circle>
                      </g>
                    </svg>
                  </div>
                </div>
              ) : (
                <div
                  key="placeholder"
                  class={`${clsPrefix}-base-loading__placeholder`}
                >
                  {this.$slots.default?.()}
                </div>
              )
          }}
        </NIconSwitchTransition>
      </div>
    )
  }
})

