  'height', 'width', 'padding', 'fontSize', 'fontWeight',
  'borderRadius', 'backgroundColor', 'color', 'whiteSpace',
  'flexBasis', 'position', 'borderTopWidth', 'lineHeight', 'cursor'
]

const report = nodes.map(el => {
