import Element exposing (Element)
import NUI.Css
import NUI.Switch
import NUI.Theme
import NUI.Types exposing (Size(..))

main : Html.Html Msg
main =
    NUI.Css.layout []
        (Element.column [ Element.spacing 24 ]
            [ NUI.Css.element
            , switch d
            , switch { d | value = True, onChange = Just Toggled }
            , switch { d | disabled = True, value = True }
            , switch { d | loading = True, rubberBand = False }
            , switch { d | round = False }
            , switch
                { d
                    | size = Large
                    , checked = Just (Element.text "Checked!")
                    , unchecked = Just (Element.text "Off")
                    , value = True
                }
            , switch
                { d
                    | railColor = Just "#2080f0"
                    , railColorActive = Just "#d03050"
                    , railStyle = Just (\checked -> [ ( "box-shadow", "0 0 0 2px rgba(0,0,0,.2)" ) ])
                    , icon = Just (Element.text "?")
                }
            ]
        )

module Main exposing (main)

import Element exposing (Element)
import Html exposing (Html)
import NUI.Css

